  function cmd(type,p={},meta={}){if(scenario==='save_failure')throw Error('Simulated save failure. Your form is retained; select Normal to retry.');const result=store.execute(type,p,actor(),meta);if(typeof result?.then==='function')result.then(r=>{if(!r?.pending)success(type,r);},()=>{});else if(!result?.pending)Promise.resolve().then(()=>success(type,result));return result;}
