    const customer=path==='customer'||path.startsWith('track/'), rider=path==='ride'||path.startsWith('ride/');
    if(customer)actorKey='customer';else if(rider){if(actor().role!=='rider'){const inv=readJSON(RIDER_KEY,null);actorKey=inv&&W.ACTORS[inv]?inv:'rider';}}else actorKey='admin';
