    document.body.classList.toggle('lang-my',lang==='my');document.body.classList.toggle('lang-en',lang!=='my');if(document.documentElement)document.documentElement.lang=lang==='my'?'my':'en';
    document.body.classList.toggle('role-customer',customer);
    document.body.classList.toggle('role-rider',rider);
    document.body.classList.toggle('role-admin',!customer&&!rider);
