    if($('#parse-results'))rows.forEach(r=>r.shown=true);
    const sheetEl=$('#app-sheet');document.body.classList.toggle('sheet-open',!!sheetEl);if(sheetEl){if(prevSheet){$('#app-sheet .sheet-body').scrollTop=sheetTop;}else{sheetEl.classList.add('enter');sheetEl.querySelector('.sheet-close')?.focus?.();}$('.sheet-scrim').onclick=e=>go(e.currentTarget.dataset.closeSheet);}
