  const hourNow=()=>Number(localTime().slice(11,13));
  const greeting=()=>{const h=hourNow();return h<12?['Good morning','မင်္ဂလာ နံနက်ခင်းပါ']:h<17?['Good afternoon','မင်္ဂလာ နေ့လယ်ခင်းပါ']:['Good evening','မင်္ဂလာ ညနေခင်းပါ'];};
  const ks=x=>Number.isFinite(x)?`${x.toLocaleString()} Ks`:'Amount unclear';
  const located=o=>live?!!o.pin:o.anchor&&['dictionary_matched','dispatcher_verified','buyer_confirmed'].includes(o.location);
  function laneOf(o){
    const t=store.triage(o.id),link=store.linkStatus(o.id),b=store.blockers(o.id);
    if(['delivered','returned','cancelled'].includes(o.state))return 'done';
    if(['out_for_delivery','retry_pending'].includes(o.state))return 'rider';
    if(o.state==='return_pending'||o.incident||o.collection?.discrepancy&&!o.collection.resolution||o.proposedPin||t.level==='red'||o.encodingReview||['locked','expired','revoked'].includes(link)||b.some(x=>/payment|policy/i.test(x)))return 'needs';
    if(o.state==='assigned')return 'ready';
    if(!located(o)&&!o.confirmation)return 'waiting';
    return 'ready';
  }
  function cardLine(o,lane){
    const link=store.linkStatus(o.id),r=store.snapshot().routes.find(r=>r.id===o.routeId),rider=Object.values(W.ACTORS).find(a=>a.id===r?.riderId)?.name;
    if(lane==='needs'){
      if(o.proposedPin)return ['amber','Buyer sent a pin to approve','Check pin'];
      if(o.state==='return_pending')return ['amber','Coming back to the hub','Open'];
      if(o.collection?.discrepancy&&!o.collection.resolution)return ['red','Cash collected differs','Check cash'];
      if(o.incident)return ['red',esc(o.incident),'Open'];
      if(link==='locked')return ['red','Buyer got the digits wrong 3 times','Open'];
      if(['expired','revoked'].includes(link))return ['red',link==='expired'?'Buyer link expired':'Buyer link revoked','New link'];
      const digits=String(o.phone||'').replace(/\D/g,'').length;
      if(!o.phone)return ['red','No phone number','Add phone'];
      if(!/^09\d{7,9}$/.test(o.phone))return ['red',`Phone has ${digits} digits, check it`,'Fix phone'];
      if(!W.PLACES.some(p=>p.id===o.areaId))return ['red',o.areaId?'Outside the service area':'Township not found','Fix address'];
      if(store.triage(o.id).level==='red')return ['red','Township switched off in hub policy','Open'];
      if(o.encodingReview)return ['amber','Check the Zawgyi conversion','Check text'];
      return ['amber','Cash amount unclear','Fix amount'];
    }
    if(lane==='waiting'){
      if(link==='not_created')return ['amber','No buyer link yet','Open'];
      if(!o.link?.shared)return ['amber','Link made, not shared yet','Open'];
      return ['amber','Link shared, waiting for an answer','Open'];
    }
    if(lane==='ready'){
      if(o.state==='assigned')return ['green',`On ${esc(o.routeId)}${rider?` with ${esc(rider)}`:''}`,'Open'];
      if(!o.received)return ['amber','Waiting for the parcel at the hub','Open'];
      return ['green',o.confirmation?`Buyer confirmed: ${esc(o.confirmation.answer)}`:'Address checked','Open'];
    }
    if(lane==='rider')return o.state==='retry_pending'?['amber',`Retry ${esc(o.time)}`,'Open']:['green',rider?`Out with ${esc(rider)}`:'Out for delivery','Open'];
    if(o.state==='delivered')return ['green',`Collected ${ks(o.collection?.actual)}`,'Open'];
    return [o.state==='cancelled'?'red':'amber',word(o.state),'Open'];
  }
  const LANES=[['needs','Needs you','စစ်ရန်','Something to fix before it can move'],['waiting','Waiting on buyer','ဝယ်သူ စောင့်ဆဲ','Buyer confirms pin and time'],['ready','Ready to send','ပို့ရန် အသင့်','Plan a route when parcels are in'],['rider','With rider','ပို့ဆောင်သူထံ','Out on the road'],['done','Delivered','ပို့ပြီး','Delivered, returned or cancelled']];
