  const deletable=o=>actor().role==='admin'&&!o.routeId&&!['out_for_delivery','delivered','returned','retry_pending','return_pending','cancelled'].includes(o.state);
  function deleteOrder(id,b){
    const card=b.closest('.card'),label=sid(id);
    if(live){dialog('Delete this order?',`<p class="sheet-copy">${esc(label)} is cancelled on the server and leaves the board. This can’t be undone.</p>`,()=>cmd('cancel',{id,reason:'Deleted from the service board'}),'Delete order');return;}
    const done=()=>{store.execute('delete',{id},W.ACTORS.admin);render();undoToast(id,label);};
    if(!card||matchMedia('(prefers-reduced-motion: reduce)').matches){if(card)card.classList.add('leaving-fade');setTimeout(done,card?120:0);return;}
    const lane=card.parentElement,sibs=[...lane.children].filter(x=>x!==card),before=new Map(sibs.map(x=>[x,x.getBoundingClientRect().top]));
    card.classList.add('leaving');
    setTimeout(()=>{card.style.display='none';sibs.forEach(x=>{const dy=before.get(x)-x.getBoundingClientRect().top;if(dy){x.animate([{transform:`translateY(${dy}px)`},{transform:'none'}],{duration:220,easing:'cubic-bezier(.23,1,.32,1)'});}});setTimeout(done,230);},170);
  }
